# Count orthogonal boundary neighbors for each enclosed cell
def count_boundary_neighbors(r, c, input_grid):
    boundary_neighbors = 0
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(input_grid) and 0 <= nc < len(input_grid[0]):
            if input_grid[nr][nc] == 1:  # boundary color
                boundary_neighbors += 1
    return boundary_neighbors

